    Get-ChildItem -Path $profilesDir -Directory | ForEach-Object {
        $basicIni = Join-Path $_.FullName "basic.ini"
        if (Test-Path $basicIni) {
            Set-IniValue $basicIni "General" "PreviewEnabled" "false"
        }
    }
}
$logsDir = Join-Path $obsData "logs"
